import {escape as e,asset,child} from './core.js?v=0.1.62-preview';
export const multiplierStates=['pre-play','first-amount','third-amount','fourth-amount','last-amount'];
export function multiplierBar(p){
 const state=multiplierStates.includes(p.state)?p.state:'pre-play',index=multiplierStates.indexOf(state),last=index===4;
 const values=index===0?['1.95','2.45','3.14','4.64','5.23','4.64']:last?['1.30','1.95','2.45','42.88','45.38','48.12','50.00']:['1.30','1.95','2.45','3.14','4.64','5.23','4.64'];
 const active=[-1,0,2,3,6][index],background=['','49d26','0aa24','0aa24','4efcf'][index],mask=index===3?'83f65':last?'131eb':'ffc56';
 return `<div class="multiplier-shell"><div class="multiplier-bar multiplier-${index}" role="group" aria-label="Multiplier progression" data-no-translate>${index?`<img class="multiplier-background" src="${asset('multiplier/'+background+'.svg')}" alt=""><img class="multiplier-highlight" src="${asset('multiplier/'+(last?'e6f46':'3e333')+'.svg')}" alt="">`:''}<div class="multiplier-window"><div class="multiplier-track" style="mask-image:url('${asset('multiplier/'+mask+'.svg')}')">${values.map((value,i)=>`<span class="multiplier-cell ${i===active?'is-current':''} ${index===1&&i>1?'is-distant':''} ${i===active+1&&active>=0?'is-next':''}" ${i===active?'aria-current="step"':''}>${e(value)}x</span>`).join('')}</div></div><button class="multiplier-arrow previous" data-action="multiplier-previous" aria-label="Previous multiplier state" ${index===0?'disabled':''}><img src="${asset('multiplier/5269f.svg')}" alt=""></button><button class="multiplier-arrow next" data-action="multiplier-next" aria-label="Next multiplier state" ${last?'disabled':''}><img src="${asset('multiplier/116d2.svg')}" alt=""></button></div></div>`;
}
export function maintenanceScreen(p){return `<section class="maintenance-screen"><div class="maintenance-logo">${child('game-logo',{src:p.logo,alt:p.gameName||'Game logo'})}</div><div class="maintenance-content"><div class="maintenance-message"><h2>${e(p.Heading)}</h2><p>${e(p.Message)}</p></div>${child('primary-button',{Label:p['Close label']||'CLOSE',action:'close'})}</div></section>`;}
